import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('exportCsv returns header for empty array', () => {
  const result = exportCsv([]);
  const lines = result.split('\n');

  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
});

test('exportCsv exports single invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);
  const lines = result.split('\n');

  assert.equal(lines.length, 3);
  assert.ok(lines[1].includes('INV-2024-0001'));
  assert.ok(lines[1].includes('C-001'));
  assert.ok(lines[1].includes('2024-02-15'));
});

test('exportCsv exports multiple invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-16',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2024-0001']).value;

  const result = exportCsv([issued1, issued2]);
  const lines = result.split('\n');

  assert.equal(lines.length, 4);
  assert.ok(lines[1].includes('INV-2024-0001'));
  assert.ok(lines[2].includes('INV-2024-0002'));
});

test('exportCsv includes customer name', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);
  const lines = result.split('\n');

  assert.ok(lines[1].includes('Acme Corp'));
});

test('exportCsv escapes customer name with comma', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);
  const lines = result.split('\n');

  assert.ok(lines[1].includes('"'));
});

test('exportCsv formats amounts as plain euros', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);
  const lines = result.split('\n');

  const fields = lines[1].split(',');
  const subtotal = fields[5];
  const vat = fields[7];

  assert.ok(subtotal.includes('.'));
  assert.ok(vat.includes('.'));
  assert.ok(!subtotal.includes('€'));
  assert.ok(!vat.includes('€'));
});

test('exportCsv includes due amount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);
  const lines = result.split('\n');

  const fields = lines[1].split(',');
  const due = fields[9];

  assert.ok(Number(due) > 0);
});

test('exportCsv includes status', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);
  const lines = result.split('\n');

  assert.ok(lines[1].includes('issued'));
});

test('exportCsv includes draft status', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const result = exportCsv([draft]);
  const lines = result.split('\n');

  assert.ok(lines[1].includes('draft'));
});

test('exportCsv includes dueDate for issued invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET30',
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);
  const lines = result.split('\n');

  assert.ok(lines[1].includes('2024-03-16'));
});

test('exportCsv handles partial payments', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const partial = recordPayment(issued, { amount: 5000, date: '2024-02-20' }).value;

  const result = exportCsv([partial]);
  const lines = result.split('\n');

  assert.ok(lines[1].includes('partially_paid'));
});

test('exportCsv calculates remaining due for partial payments', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const partial = recordPayment(issued, { amount: 5000, date: '2024-02-20' }).value;

  const result = exportCsv([partial]);
  const lines = result.split('\n');

  const fields = lines[1].split(',');
  const due = Number(fields[9]);
  const total = Number(fields[8]);

  assert.ok(due < total);
  assert.ok(due > 0);
});

test('exportCsv lines end with newline', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);

  assert.ok(result.endsWith('\n'));
});

test('exportCsv header matches field count', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);
  const lines = result.split('\n');

  const headerFields = lines[0].split(',');
  const dataFields = lines[1].split(',');

  assert.equal(headerFields.length, dataFields.length);
});

test('exportCsv formats zero amounts correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);
  const lines = result.split('\n');

  assert.ok(lines[1].includes('0.00'));
});

test('exportCsv preserves order of invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-16',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-17',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2024-0001']).value;
  const issued3 = issueInvoice(inv3, ['INV-2024-0001', 'INV-2024-0002']).value;

  const result = exportCsv([issued1, issued3, issued2]);
  const lines = result.split('\n');

  assert.ok(lines[1].includes('INV-2024-0001'));
  assert.ok(lines[2].includes('INV-2024-0003'));
  assert.ok(lines[3].includes('INV-2024-0002'));
});

test('exportCsv escapes quotes in fields', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);
  const lines = result.split('\n');

  assert.ok(lines[1].includes('""'));
});

test('exportCsv header has correct columns', () => {
  const result = exportCsv([]);
  const lines = result.split('\n');
  const header = lines[0];

  const columns = [
    'number',
    'customer',
    'issueDate',
    'dueDate',
    'status',
    'subtotal',
    'discount',
    'vat',
    'total',
    'due',
  ];

  assert.equal(header, columns.join(','));
});

test('exportCsv with draft invoice has empty dueDate', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const result = exportCsv([draft]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');

  assert.equal(fields[3], '');
});

test('exportCsv amount has exactly 2 decimals', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');

  const amounts = [fields[5], fields[6], fields[7], fields[8], fields[9]];
  amounts.forEach((amount) => {
    const parts = amount.split('.');
    assert.equal(parts.length, 2);
    assert.equal(parts[1].length, 2);
  });
});

